content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Procurement Manager",
      "description": "role that handles buying activities and contacts suppliers"
    },
    {
      "name": "Price Quote Request",
      "description": "request sent to a supplier asking for pricing and terms"
    },
    {
      "name": "Supplier",
      "description": "party that sells goods and provides documents"
    },
    {
      "name": "Compliance Document",
      "description": "papers proving the goods meet import and safety rules"
    },
    {
      "name": "Local Import Rules",
      "description": "regulations the goods must follow in the destination country"
    },
    {
      "name": "Proforma Invoice",
      "description": "initial invoice showing product cost and shipping terms",
      "attributes": [
        "Product Cost",
        "Shipping Terms"
      ]
    },
    {
      "name": "Product Cost",
      "description": "price charged for the goods"
    },
    {
      "name": "Shipping Terms",
      "description": "conditions that define who pays and handles transport"
    },
    {
      "name": "Shipment Schedule",
      "description": "supplier’s planned timeline for sending the goods"
    },
    {
      "name": "Delivery Expectation",
      "description": "buyer’s desired arrival time for the goods"
    },
    {
      "name": "Buyer",
      "description": "organization receiving and paying for the goods"
    },
    {
      "name": "Logistics Coordinator",
      "description": "role that arranges transport and tracks freight"
    },
    {
      "name": "International Freight Booking",
      "description": "reservation for cargo transport with a carrier",
      "attributes": [
        "Carrier"
      ]
    },
    {
      "name": "Carrier",
      "description": "company that physically transports the shipment"
    },
    {
      "name": "Arrival Update",
      "description": "status info about when the shipment is expected to arrive"
    },
    {
      "name": "Customs Specialist",
      "description": "role that handles the paperwork for clearing goods at the border"
    },
    {
      "name": "Code Check",
      "description": "verification of product classification codes for customs"
    },
    {
      "name": "Warehouse Receiver",
      "description": "role that inspects and logs goods when they arrive"
    },
    {
      "name": "Inventory",
      "description": "stock records that show what goods are available",
      "attributes": [
        "Shipment"
      ]
    },
    {
      "name": "Shipment",
      "description": "set of goods transported together",
      "attributes": [
        "Customs Declaration",
        "International Freight Booking",
        "Shipment Schedule"
      ]
    },
    {
      "name": "Customs Declaration",
      "description": "document submitted to customs describing the goods"
    }
  ]
}
```
